-- ============================================================
-- 0021_reference: what every firm reads and no firm writes.
--
--   courts         the state courts and their code in the unique case number
--                  (Resolução CNJ 65/2008: segment 8, TR 01 to 27);
--   court_systems  which filing system a court uses for each kind of
--                  proceeding, since when, with its file limits and where
--                  the fact came from. Seeded from a sample of the public
--                  DJEN API (`scripts/djen-systems.mjs`), every row
--                  unconfirmed until a person checks it against the court's
--                  acts: a sample shows where the cases IN COURSE live;
--   airports       the airports with scheduled service and an IATA code,
--                  from OurAirports (public domain), read on 2026-10-09;
--   airlines       the airlines a firm's cases name, by IATA designator.
--
-- Configuration is data: a court that changes its system, an airport that
-- opens, an airline's legal entity are a row, never a deploy. Only the
-- platform's operator changes them, through the functions at the end.
-- ============================================================

-- ---------- Courts ----------

create table public.courts (
  acronym text primary key,
  name text not null,
  uf text not null unique,
  -- The segment and the court in the unique case number: 8 and 09 for TJGO.
  cnj_segment text not null default '8',
  cnj_code text not null,
  unique (cnj_segment, cnj_code),
  constraint courts_acronym_check check (acronym ~ '^TJ[A-Z]{2,3}$'),
  constraint courts_uf_check check (uf ~ '^[A-Z]{2}$'),
  constraint courts_code_check check (cnj_segment ~ '^[0-9]$' and cnj_code ~ '^[0-9]{2}$')
);

alter table public.courts enable row level security;
create policy "courts_select_all" on public.courts for select to anon, authenticated using (true);
grant select on table public.courts to anon, authenticated;

-- The table of the resolution (Anexo VI, "Tribunais de Justiça dos Estados e do
