-- ---------- The system each court uses ----------

create table public.court_systems (
  court text not null references public.courts (acronym) on delete cascade,
  -- `juizado`: the small-claims court, where adults go. `comum`: the civil court, where a minor goes.
  proceeding_kind text not null,
  system text not null,
  -- The host the court's links point to, as the DJEN showed it.
  host text,
  -- Since when new cases of that kind go to that system, when an act says so.
  since date,
  -- The largest file the system takes, when known.
  max_file_bytes bigint,
  -- Where the fact came from: a DJEN sample, an act of the court, a test of the filing station.
  source text not null,
  sample_count integer,
  sample_total integer,
  sampled_on date,
  -- A person checked it against the court's acts.
  confirmed boolean not null default false,
  notes text,
  updated_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now(),
  primary key (court, proceeding_kind),
  constraint court_systems_kind_check check (proceeding_kind in ('juizado', 'comum')),
  constraint court_systems_system_check check (system in ('projudi', 'eproc', 'pje', 'esaj', 'outro')),
  constraint court_systems_limits_check check (max_file_bytes is null or max_file_bytes > 0),
  constraint court_systems_text_check check (char_length(source) <= 500 and (notes is null or char_length(notes) <= 2000))
);

alter table public.court_systems enable row level security;
create policy "court_systems_select_all" on public.court_systems for select to authenticated using (true);
grant select on table public.court_systems to authenticated;

-- ---------- Airports ----------

create table public.airports (
  iata text primary key,
  icao text,
  name text not null,
  city text,
  -- ISO 3166-1 alpha-2.
  country text not null,
  -- The state, for an airport in Brazil.
  uf text,
  constraint airports_iata_check check (iata ~ '^[A-Z]{3}$'),
  constraint airports_icao_check check (icao is null or icao ~ '^[A-Z0-9]{4}$'),
  constraint airports_country_check check (country ~ '^[A-Z]{2}$'),
  constraint airports_uf_check check ((country = 'BR') = (uf is not null) and (uf is null or uf ~ '^[A-Z]{2}$'))
);

create index airports_brazil_idx on public.airports (uf) where country = 'BR';

alter table public.airports enable row level security;
create policy "airports_select_all" on public.airports for select to anon, authenticated using (true);
grant select on table public.airports to anon, authenticated;

-- ---------- Airlines ----------

create table public.airlines (
  iata text primary key,
  name text not null,
  -- ISO 3166-1 alpha-2 of the airline's home.
  country text,
  -- The company that answers in court in Brazil, filled in by the operator: the
  -- petition names it, so it is never guessed.
  legal_name text,
  cnpj text,
  active boolean not null default true,
  updated_at timestamptz not null default now(),
  constraint airlines_iata_check check (iata ~ '^[A-Z0-9]{2}$' and iata !~ '^[0-9]{2}$'),
  constraint airlines_country_check check (country is null or country ~ '^[A-Z]{2}$'),
  constraint airlines_cnpj_check check (cnpj is null or (cnpj ~ '^[0-9]{14}$')),
  constraint airlines_name_check check (char_length(btrim(name)) between 2 and 120)
);

alter table public.airlines enable row level security;
create policy "airlines_select_all" on public.airlines for select to anon, authenticated using (true);
grant select on table public.airlines to anon, authenticated;

