-- ---------- What only the operator changes ----------

/**
 * Records which system a court uses for a kind of proceeding, as the operator
 * checked it: an act of the court, a test at the filing station. A row the
 * operator confirms is never overwritten by a later DJEN sample.
 */
create or replace function public.admin_set_court_system(
  target_court text,
  target_kind text,
  target_system text,
  target_since date,
  target_max_file_bytes bigint,
  target_source text,
  target_notes text,
  target_confirmed boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  caller uuid := auth.uid();
  clean_source text := nullif(btrim(coalesce(target_source, '')), '');
begin
  if caller is null or not public.is_superadmin() or public.is_impersonated() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
  if not exists (select 1 from public.courts c where c.acronym = target_court) then
    return jsonb_build_object('ok', false, 'code', 'court_not_found');
  end if;
  if clean_source is null or char_length(clean_source) < 8 then
    return jsonb_build_object('ok', false, 'code', 'source_required');
  end if;

  insert into public.court_systems as cs (
    court, proceeding_kind, system, since, max_file_bytes, source, notes, confirmed, updated_by
  ) values (
    target_court, target_kind, target_system, target_since, target_max_file_bytes, left(clean_source, 500),
    nullif(btrim(coalesce(target_notes, '')), ''), coalesce(target_confirmed, false), caller
  )
  on conflict (court, proceeding_kind) do update set
    system = excluded.system,
    since = excluded.since,
    max_file_bytes = excluded.max_file_bytes,
    source = excluded.source,
    notes = excluded.notes,
    confirmed = excluded.confirmed,
    updated_by = caller,
    updated_at = now();

  insert into public.audit_events (org_id, actor_id, action, entity_type, entity_id, metadata)
  values (null, caller, 'admin.court_system.set', 'court_system', target_court || '/' || target_kind,
          jsonb_build_object('system', target_system, 'confirmed', coalesce(target_confirmed, false)));
  return jsonb_build_object('ok', true, 'code', 'saved');
exception when check_violation then
  return jsonb_build_object('ok', false, 'code', 'invalid_value');
end;
$$;

revoke all on function public.admin_set_court_system(text, text, text, date, bigint, text, text, boolean) from public, anon;
grant execute on function public.admin_set_court_system(text, text, text, date, bigint, text, text, boolean) to authenticated;

/** Adds an airline or changes what is known of it: its name, its legal entity in Brazil, whether it still flies. */
create or replace function public.admin_set_airline(
  target_iata text,
  target_name text,
  target_country text,
  target_legal_name text,
  target_cnpj text,
  target_active boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  caller uuid := auth.uid();
  digits text := nullif(regexp_replace(coalesce(target_cnpj, ''), '\D', '', 'g'), '');
begin
  if caller is null or not public.is_superadmin() or public.is_impersonated() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  insert into public.airlines as a (iata, name, country, legal_name, cnpj, active)
  values (upper(btrim(target_iata)), btrim(target_name), nullif(upper(btrim(coalesce(target_country, ''))), ''),
          nullif(btrim(coalesce(target_legal_name, '')), ''), digits, coalesce(target_active, true))
  on conflict (iata) do update set
    name = excluded.name,
    country = excluded.country,
    legal_name = excluded.legal_name,
    cnpj = excluded.cnpj,
    active = excluded.active,
    updated_at = now();

  insert into public.audit_events (org_id, actor_id, action, entity_type, entity_id, metadata)
  values (null, caller, 'admin.airline.set', 'airline', upper(btrim(target_iata)),
          jsonb_build_object('active', coalesce(target_active, true)));
  return jsonb_build_object('ok', true, 'code', 'saved');
exception when check_violation or not_null_violation then
  return jsonb_build_object('ok', false, 'code', 'invalid_value');
end;
$$;

revoke all on function public.admin_set_airline(text, text, text, text, text, boolean) from public, anon;
grant execute on function public.admin_set_airline(text, text, text, text, text, boolean) to authenticated;

