-- What the sample cannot show, from what was read of the courts.
update public.court_systems set notes =
  'A amostra mostra o Projudi dos processos em curso. Os novos processos de juizado vão para o eproc desde 02/07/2026: confirmar com o ato do tribunal antes de montar um pacote.'
where court = 'TJPR' and proceeding_kind = 'juizado';
